@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
}

/*  全局核心控制台 (所有设置都在这里)  */

/* 💻 【第一部分：PC端 & 全局变量设定】 */
:root {

    --main-body-font: "";
    --char-name-font: "";

    /*  1.代码块/引用 */
    --可爱-虚线色: #8CA57C;
    --可爱-玻璃底色: rgba(255, 255, 255, 0.45);
    --可爱-文本色: #5c7a68;
    --可爱-高亮色: #66b284;
    --可爱-圆角: 18px; 
    --可爱-右上挂件-图: url('https://iili.io/CeuZb2f.png'); 
    --可爱-右上挂件-尺寸: 155px;
    --可爱-挂件-上移: -75px; 
    --可爱-挂件-右移: -12px;

    /* 2. 顶栏 (Top Bar) */
    --顶栏-背景图: url('https://iili.io/C16NZzJ.png');
    --顶栏-边框色: #ffffff;
    --顶栏-背景底色: transparent;
    --顶栏-高度-pc: 0px;
    --顶栏-画板宽度-pc: 100vw;       
    --顶栏-画板高度-pc: 100px;        
    --顶栏-图片缩放-pc: 70% 100%;   
    --顶栏-图标-尺寸-pc: clamp(32px, 3vw, 42px);
    --顶栏-图标-偏移-左右-pc: 0px;  
    --顶栏-图标-偏移-上下-pc: 4px;  

    --顶栏-图标-激活-左侧菜单: url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-系统设置: url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-高级文本: url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-世界书:   url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-用户设置: url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-Logo区:   url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-背景设置: url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-扩展插件: url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-人格管理: url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-表格列表: url('https://iili.io/CeLzNta.png');
    --顶栏-图标-激活-右侧菜单: url('https://iili.io/CeLzNta.png');

    /*  3. 气泡与头像 (Message Bubble) */
    --气泡-大小-pc: 98%;
    --气泡-头像装饰顶图: url('https://iili.io/CeS6ZVj.png'); 
    --气泡-中: url('https://iili.io/C1rL3xI.png');
    --气泡-下: url('https://iili.io/C1rLKiX.png');

    --气泡-头像-宽度比例-pc: 22%;     
    --气泡-头像-宽高比: 24 / 25;  
    --气泡-头像-X轴-pc: 26.2%;
    --气泡-头像-Y轴-pc: 10cqw;      
    --气泡-头像-圆角-pc: 6px; 
    --气泡-文字下推-pc: 35%;          
    --气泡-mes-seal-height-pc: 540px;
    --气泡-中部下推-pc: 120px;
    --气泡-中部上推-pc: 60px;

    /*  4. 名字、时间与小标签 (Bubble Header) */
    --气泡-内容-起点-X: 38.5%;        
    --气泡-内容-起点-Y: -9vw;          
    --气泡-名字-字号-pc: clamp(20px, 1.8vw, 28px);
    --气泡-时间-字号-pc: clamp(9px, 0.8vw, 13px);
    --气泡-名字-字号-pc: clamp(20px, 1.8vw, 28px);
    --气泡-时间-字号-pc: clamp(9px, 0.8vw, 13px);

    /* (1em=1个字, 5.5em=最多5个字) */
    --气泡-名字-最大宽度-pc: 7.5em; 
    --气泡-时间-独立X偏移-pc: 0vw;       
    --气泡-时间-下移偏移: 7.5vw;      
    --气泡-标签-字号-pc: clamp(10px, 0.85vw, 13px);
    --气泡-标签-Y轴高度-pc: 9.2vw;      
    --气泡-标签-X轴起点-pc: 39%;    
    --标签-文字色: #8CA57C;          
    --标签-前缀图标: "🍏";
    --标签-间距: 1.5vw;

    /* 5. 正文排版与思维链 (Bubble Content) */
    --气泡-正文-上边距-pc: 4vw;   
    --气泡-正文-下边距-pc: 15vw;   
    --气泡-正文-左边距-pc: 7%;      
    --气泡-正文-右边距-pc: 8%;      

    --气泡-思维链-图标: url('https://iili.io/Ce0qDJe.png'); 
    --气泡-思维链-宽-pc: clamp(35px, 75vw, 105px);
    --气泡-思维链-高-pc: clamp(35px, 75vw, 105px);
    --气泡-思维链-X轴-pc: 8%;      
    --气泡-思维链-Y轴-pc: -2vw;     

    --气泡-思维链框-宽-pc: 95%; 
    --气泡-思维链框-最大宽-pc: clamp(250px, 45vw, 350px); 
    --气泡-思维链框-上边距-pc: 1.5vw;
    --气泡-思维链框-下边距-pc: 1vw;
    --气泡-思维链框-左边距-pc: 12%;
    --气泡-思维链框-右边距-pc: 2%;
    --气泡-思维链框-内边距-pc: 1vw 1.2vw;
    --气泡-思维链框-视窗化: 76vw;

    /*  6. 气泡翻页 (Swiper) */
    --气泡-翻页-左图标: url('https://iili.io/Ce1x70Q.png');
--气泡-翻页-右图标: url('https://iili.io/Ce1x5qx.png');
    --气泡-翻页-左镜像: 1;
    --气泡-翻页-右镜像: 1; 
    --气泡-翻页-图标尺寸: 95px; 
    --气泡-计数器-字号: 14px;
    --气泡-计数器-颜色: #333333;
    --气泡-翻页-左-Y轴-pc: 102px; /* 距离底部 */
    --气泡-翻页-左-X轴-pc: 175px; /* 距离左边 */
    --气泡-翻页-中-Y轴-pc: 53px;  /* 距离底部 */
    --气泡-翻页-中-X轴偏移-pc: -1770%; /* 水平偏移 */
    --气泡-翻页-右-Y轴-pc: 42px; /* 距离底部 */
    --气泡-翻页-右-X轴-pc: 595px;/* 距离右边 */

    /*  7. 气泡操作按钮 */
    --气泡按钮-编辑-图片: url('https://iili.io/CevzESp.png');
    --气泡按钮-更多-图片: url('https://iili.io/CevBVgS.png');
    --气泡按钮-编辑-镜像: 1; 
    --气泡按钮-更多-镜像: 1;
    --气泡按钮-宽度: clamp(25px, 4vw, 35px); 
    --气泡按钮-高度: clamp(25px, 4vw, 35px);
    --气泡按钮-间距: 1vw; 
    --气泡按钮组-上下浮动: 6vw;   
    --气泡按钮组-左右浮动: 8vw;    

    /*   8. 底栏输入区 */
    --底栏-主题色: #7a92a3; 
    --底栏-背景色: #ffffff; 
    --底栏-线框色: #eef2f5; 
    --底栏-上下浮动: -0.5vw; 
    --底栏-左右浮动: 0vw;  
    --底栏-左右边距: 0vw;  

    --底栏-提示词: "Ring｜LOVE正在投递...";
    --底栏-提示词-左右偏移: -2vw; 
    --底栏-选项-图片: url('https://iili.io/BLmvS5l.png');      
    --底栏-选项-尺寸: clamp(16px, 1.8vw, 24px);
    --底栏-扩展-图片: url('https://iili.io/BLmvS5l.png');
    --底栏-扩展-宽: clamp(25px, 3vw, 40px);
    --底栏-扩展-高: clamp(15px, 2vw, 25px);       
    --底栏-发送-图片: url('https://iili.io/BLmvS5l.png');
    --底栏-发送-尺寸: clamp(24px, 2.5vw, 36px); 

    /* 9. 全局组件 */
    --加载图-链接: url('https://iili.io/CiDHexj.png');
    --加载图-尺寸: clamp(100px, 45vw, 190px); 
    --跳动-幅度: -12px;
    --跳动-速度: 1.5s;
}

/* 📱 【移动端专属覆盖控制台】 */
@media screen and (max-width: 768px) {
    :root {
        /* 气泡 */
        --气泡-大小-pc: 100%;
        --气泡-头像-宽度比例-pc: 22.8%; 
        --气泡-头像-Y轴-pc: 15.2cqw;     
        --气泡-头像-圆角-pc: 1px;
        --气泡-文字下推-pc: 30%;      
        --气泡-mes-seal-height-pc: 225px;
        --气泡-中部下推-m: 60px;    
        --气泡-中部上推-m: 20px;   
        --气泡-内容-起点-X: 40%;
        --气泡-内容-起点-Y: -8.5vw;
        --气泡-名字-字号-pc: clamp(14px, 8.5vw, 18px);
        --气泡-时间-字号-pc: clamp(8px, 2.5vw, 14px);
        --气泡-名字-字号-pc: clamp(14px, 8.5vw, 18px);
        --气泡-时间-字号-pc: clamp(8px, 2.5vw, 14px);
        --气泡-名字-最大宽度-pc: 5.5em; 
        --气泡-时间-独立X偏移-pc: 0vw;
        --气泡-时间-下移偏移: -6.5vw; 
        --气泡-标签-Y轴高度-pc: 31.5vw;
        --气泡-标签-X轴起点-pc: 35%; 
        --标签框-高度-pc: clamp(18px, 4.5vw, 22px);
        --气泡-正文-上边距-pc: 14vw;  
        --气泡-正文-下边距-pc: 20vw;
        --气泡-正文-左边距-pc: 7%;    
        --气泡-正文-右边距-pc: 7%;   
        --气泡-思维链-宽-pc: clamp(30px, 14.5vw, 55px);
    --气泡-思维链-高-pc: clamp(30px, 14.5vw, 55px);
        --气泡-思维链-X轴-pc: 7.5%;
        --气泡-思维链-Y轴-pc: 2.4vw;
        --气泡-思维链框-宽-pc: 98%;
        --气泡-思维链框-最大宽-pc: 100%; 
        --气泡-思维链框-上边距-pc: 9vw;
        --气泡-思维链框-下边距-pc: 3vw;
        --气泡-思维链框-左边距-pc: 6%;
        --气泡-思维链框-右边距-pc: 1%;
        --气泡-思维链框-内边距-pc: 3vw 2vw;
        --气泡-翻页-图标尺寸-m: 60px; 

        --气泡-翻页-左-Y轴-m: 60px;
        --气泡-翻页-左-X轴-m: 85px;

        --气泡-翻页-中-Y轴-m: 20px;
        --气泡-翻页-中-X轴偏移-m: -790%;

        --气泡-翻页-右-Y轴-m: 10px;
        --气泡-翻页-右-X轴-m: 215px;
        --气泡按钮-宽度: 6vw;
        --气泡按钮-高度: 6vw;
        --气泡按钮-间距: 2vw;
        --气泡按钮组-上下浮动: 11vw; 
        --气泡按钮组-左右浮动: 12vw; 

        --顶栏-高度-m: 38px;
        --顶栏-画板宽度-m: 100vw;       
        --顶栏-画板高度-m: 180px;        
        --顶栏-图片缩放-m: 100% 40%;   
        --顶栏-图标-尺寸-m: clamp(20px, 6.5vw, 26px);
        --顶栏-图标-偏移-左右-m: 0px;
        --顶栏-图标-偏移-上下-m: 2px;

        /* 底栏 */  
