    }
}

/* 以下为渲染逻辑区 (代码与上面一一对应，无需修改)  */

/* --- 气泡、头像与封底 --- */
.mes { 
    position: relative; 
    isolation: isolate; 
    width: var(--气泡-大小-pc); 
    padding-top: var(--气泡-文字下推-pc) !important; 
    margin: 223px auto 85px !important; 
    color: var(--mes-text-color) !important; 
    background: transparent !important; 
}

.mes::before { 
    content: ''; 
    position: absolute; left: 0; width: 100%; 
    top: var(--气泡-中部下推-pc) !important;       
    bottom: var(--气泡-中部上推-pc) !important;   
    background: var(--气泡-中) center top / 100% auto repeat-y !important; 
    z-index: -2 !important; 
    pointer-events: none !important; 
}

.mes::after { 
    content: ''; 
    position: absolute; 
    top: 0; left: 0; width: 100%; height: 100%; 
    background: 
        var(--气泡-下) center calc(100% + 1px) / 100% auto no-repeat !important; 
    z-index: -1 !important; 
    pointer-events: none !important; 
}

.mes .avatar { 
    position: absolute !important; 
    top: var(--气泡-头像-Y轴-pc) !important; 
    left: var(--气泡-头像-X轴-pc) !important; 
    transform: translateX(-60%) rotate(2deg) !important; 
    width: var(--气泡-头像-宽度比例-pc) !important; 
    aspect-ratio: var(--气泡-头像-宽高比) !important; 
    height: auto !important; 
    border-radius: 50% !important; 
    z-index: 1 !important; 
    overflow: hidden !important; 
    padding: 0 !important; 
    background-color: transparent !important; 
    border: none !important; 
    box-shadow: none !important; 
}

.mes .avatar img { 
    width: 100% !important; 
    height: 100% !important; 
    object-fit: cover !important; 
    border-radius: 50% !important; 
}

.mes .mesAvatarWrapper {
    position: static !important; 
}
.mes .mesAvatarWrapper::after {
    content: ''; 
    position: absolute; 
    top: 0; left: 0; width: 100%; height: 100%; 
    background: var(--气泡-头像装饰顶图) top center / 100% auto no-repeat !important; 
    z-index: 3 !important; 
    pointer-events: none !important; 
}

@media screen and (max-width: 768px) { 
    #chat .mes { 
        padding-right: 16px !important; 
        padding-bottom: 36px !important; 
        padding-left: 0px !important; 
        margin: var(--mes-margin-mobile, 19px auto 15px) !important; 
    } 
    .mes-content { padding: 14px !important; } 

    #chat .mes::before {
        top: var(--气泡-中部下推-m) !important;       
        bottom: var(--气泡-中部上推-m) !important; 
    }
}

/* --- 杂项与滚动条 --- */
.regex-script-label { --flex-wrap: wrap; border-radius: var(--genericRadius) !important; background-color: var(--buttonFill) !important; gap: 2px !important; padding-top: 2px !important; padding-bottom: 4px !important; margin-right: 35px !important; }
::-webkit-scrollbar { width: 0; height: 0; display: none; }
* { scrollbar-width: none; -ms-overflow-style: none; }
#chat, .mes_block, #send_textarea, .drawer-content, .settings-panel { overflow-y: auto; overflow-x: hidden; }
.textarea_compact { scrollbar-width: thin !important; scrollbar-color: #000 transparent !important; -ms-overflow-style: auto !important; }
.mes_block { position: relative; z-index: 3; } div.mess { position: relative; z-index: 999 !important; isolation: isolate; }
#HotSwapWrapper { overflow: hidden !important; } #HotSwapWrapper > div { overflow-x: auto !important; overflow-y: hidden !important; display: flex !important; flex-wrap: nowrap !important; justify-content: flex-start !important; gap: 8px !important; padding-bottom: 8px !important; min-height: calc(var(--avatar-base-height) * 1.2); scrollbar-width: none !important; }
#HotSwapWrapper > div::-webkit-scrollbar { display: none !important; } #completion_prompt_manager .completion_prompt_manager_header { color: var(--SmartThemeBodyColor); }
*:disabled, *[disabled], *[aria-disabled="true"], *[readonly], .disabled, .inactive, .disabled *, .inactive * { color: inherit !important; -webkit-text-fill-color: inherit !important; text-fill-color: inherit !important; opacity: 1 !important; filter: none !important; }
[class*="disabled"]:not(.keep-style), [class*="disabled"] *:not(.keep-style), [class*="is-disabled"]:not(.keep-style), [class*="is-disabled"] *:not(.keep-style) { color: inherit !important; opacity: 1 !important; }
#char-management-dropdown { width: 100vw; } #avatar_div { flex-direction: column; } #avatar_controls { align-items: center; }
#rm_button_selected_ch h2::after { content: " —爱是不可多得的神迹" !important; font-family: "SimSun", "STSong", serif !important; font-size: 0.5em !important; color: #999999 !important; font-weight: normal !important; letter-spacing: 2px !important; margin-left: 15px !important; vertical-align: baseline !important; font-style: italic !important; display: inline-block !important; opacity: 0.8 !important; }
@media screen and (max-width: 768px) { #rm_button_selected_ch h2::after { display: block !important; margin-left: 0 !important; margin-top: 5px !important; font-size: 0.45em !important; } }

.mes_text { line-height: 1.7 !important; text-align: justify !important; text-justify: inter-word; hyphens: auto; width: 100% !important; box-sizing: border-box !important; margin-left: 0px !important; padding-top: var(--气泡-正文-上边距-pc) !important; padding-bottom: var(--气泡-正文-下边距-pc) !important; padding-left: var(--气泡-正文-左边距-pc) !important; padding-right: var(--气泡-正文-右边距-pc) !important; }

/* 三只小猪小标签 */
.mesIDDisplay, .mes_timer, .tokenCounterDisplay { 
    position: absolute !important; 
    z-index: 25 !important; 

    display: inline-flex !important; 
    align-items: center !important; 
    justify-content: center !important; 
    white-space: nowrap !important; 
    box-sizing: border-box !important;

    height: var(--标签框-高度-pc) !important;
    padding: var(--标签框-内边距-pc) !important;
    color: var(--标签框-文字色) !important;
    top: var(--气泡-标签-Y轴高度-pc) !important; 
    font-family: 'Courier New', 'Consolas', monospace, "SimSun" !important;
    font-size: var(--气泡-标签-字号-pc) !important; 
    font-weight: bold !important;
    letter-spacing: 0.5px !important;
    background: var(--标签框-背景色) !important;
    box-shadow: none !important; 
    backdrop-filter: blur(4px) !important;
    -webkit-backdrop-filter: blur(4px) !important;
    border-top: 1px solid var(--标签框-边框色) !important;
    border-bottom: 1px solid var(--标签框-边框色) !important;
    border-radius: 0 !important; 
}

.mesIDDisplay i, .mes_timer i, .tokenCounterDisplay i {
    display: none !important;
}

.mesIDDisplay::before, 
.mes_timer::before, 
.tokenCounterDisplay::before {
    content: var(--标签-前缀图标) !important;
    display: inline-block !important;
    font-size: 1.1em !important;
    margin-right: 4px !important; 
    width: auto !important; height: auto !important;
    background: transparent !important; box-shadow: none !important;
    border-radius: 0 !important; animation: none !important;
}

.mes_timer { visibility: visible !important; } 
.mes[is_user="true"] .mes_timer { display: none !important; }

.mesIDDisplay { 
    anchor-name: --id-tag; 
    left: var(--气泡-标签-X轴起点-pc) !important; 
    border-left: 1px solid var(--标签框-边框色) !important;
    border-radius: 0 !important; 
}

.mes_timer {
    anchor-name: --timer-tag; 
    border-left: 1px solid var(--标签框-分割线) !important;
}

.tokenCounterDisplay {
    border-left: 1px solid var(--标签框-分割线) !important;
    border-right: 1px solid var(--标签框-边框色) !important;
    border-radius: 0 !important; 
}

@supports (left: anchor(right)) { 
    .mes_timer { left: anchor(--id-tag right) !important; } 
